{
  "implementation": "def solve(case):
    # Extract fields
    initial_state = case.get('initial_state')
    max_steps = case.get('max_steps')
    tool_observations = case.get('tool_observations')
    transitions = case.get('transitions')

    # Validate required fields
    if initial_state is None or not isinstance(initial_state, str):
        raise ValueError("initial_state must be a string")
    if not isinstance(max_steps, int) or max_steps < 0:
        raise ValueError("max_steps must be a non-negative integer")
    if not isinstance(tool_observations, dict):
        raise ValueError("tool_observations must be a dictionary")
    if not isinstance(transitions, dict):
        raise ValueError("transitions must be a dictionary")
    if initial_state not in transitions:
        raise ValueError(f"initial_state '{initial_state}' not found in transitions")

    # Validate each transition definition
    for state_name, state_info in transitions.items():
        if not isinstance(state_info, dict):
            raise ValueError(f"Transition for '{state_name}' is not a dict")
        kind = state_info.get('kind')
        if kind == 'action':
            if 'action' not in state_info or not isinstance(state_info['action'], str):
                raise ValueError(f"Action state '{state_name}' missing 'action' string")
            if 'next_by_observation' not in state_info or not isinstance(state_info['next_by_observation'], dict):
                raise ValueError(f"Action state '{state_name}' missing 'next_by_observation' dict")
            if 'default_next' not in state_info or not isinstance(state_info['default_next'], str):
                raise ValueError(f"Action state '{state_name}' missing 'default_next' string")
            # Ensure the tool exists in tool_observations
            if state_info['action'] not in tool_observations:
                raise ValueError(f"Tool '{state_info['action']}' in state '{state_name}' not found in tool_observations")
        elif kind == 'final':
            if 'value' not in state_info or not isinstance(state_info['value'], str):
                raise ValueError(f"Final state '{state_name}' missing 'value' string")
        else:
            raise ValueError(f"Unknown transition kind '{kind}' in state '{state_name}'")

    # Run the bounded ReAct loop
    current_state = initial_state
    steps_taken = 0
    trace = []
    final_value = None
    status = None

    while steps_taken < max_steps:
        if current_state not in transitions:
            raise ValueError(f"Reached undefined state '{current_state}'")
        state_info = transitions[current_state]

        if state_info['kind'] == 'final':
            final_value = state_info['value']
            status = 'completed'
            break

        # It's an action state
        action = state_info['action']
        observation = tool_observations[action]
        next_state = state_info['next_by_observation'].get(observation, state_info['default_next'])

        trace.append({
            'step': steps_taken + 1,
            'action': action,
            'observation': observation,
            'state': next_state
        })

        current_state = next_state
        steps_taken += 1

    else:
        # Loop exhausted without reaching final state
        status = 'max_steps_reached'
        final_value = None

    if status is None:
        # Should not happen, but as safety
        status = 'max_steps_reached'
        final_value = None

    return {
        'final': final_value,
        'status': status,
        'trace': trace
    }"
}
